public class RequiredAttributeDetector extends Detector implements XmlScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(
            RequiredAttributeDetector.class,
            Scope.RESOURCE_FILE_SCOPE
    );

    public static final Issue ISSUE = Issue.create(
            "RequiredSize",
            "Missing layout width or height",
            "All views must specify an explicit `layout_width` and `layout_height` attribute. ...",
            Category.CORRECTNESS,
            8,
            Severity.FATAL,
            IMPLEMENTATION
    );

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String tag = element.getTagName();
        if (tag == null) return;
        String localName = getLocalName(tag);
        if (localName == null) return;

        if (isSpecialTag(localName)) {
            return;
        }

        if (isGridLayout(element, localName)) {
            return;
        }

        // If a style is applied, the size may be defined there.
        if (element.hasAttributeNS(ANDROID_URI, ATTR_STYLE)) {
            return;
        }

        boolean hasWidth = element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH);
        boolean hasHeight = element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT);

        if (!hasWidth || !hasHeight) {
            String missing = !hasWidth ? ATTR_LAYOUT_WIDTH : ATTR_LAYOUT_HEIGHT;
            context.report(ISSUE, element, context.getLocation(element),
                    "Missing required `" + missing + "` attribute");
        }
    }

    private static String getLocalName(String tag) {
        int colon = tag.indexOf(':');
        return colon == -1 ? tag : tag.substring(colon + 1);
    }

    private static boolean isSpecialTag(String localName) {
        return localName.equals(TAG_INCLUDE)
                || localName.equals(TAG_MERGE)
                || localName.equals(TAG_REQUEST_FOCUS)
                || localName.equals("fragment")
                || localName.equals("layout");
    }

    private static boolean isGridLayout(Element element, String localName) {
        if (localName.equals("GridLayout")) {
            return true;
        }
        if (localName.equals(TAG_VIEW)) {
            String className = element.getAttribute("class");
            if (className != null && className.endsWith("GridLayout")) {
                return true;
            }
        }
        return false;
    }
}
```

