    if (!parentName.startsWith("layout")) {
        return false;
    }
    File resDir = parent.getParentFile();
    if (resDir == null) {
        return false;
    }
    File[] children = resDir.listFiles();
    if (children == null) {
        return false;
    }
    for (File child : children) {
